// --- mutation 保存异步开关 ---
// 1. 在 ST QR 栏注入一个开关按钮（bolt ⚡ = 异步开 / bolt-slash = 同步关，active 高亮区分）
// 2. 点击翻转 extension_settings.tavernHelperToggle.mutationAsync 并 saveSettingsDebounced() 持久化
// 3. script.js 的 saveChatConditional 在运行时读取该值（默认关 = 同步），无需重启/重打包
// 4. 顺带暴露 parent.window.__mutationAsyncToggle 供循环任务/斜杠命令调用：
//      parent.window.__mutationAsyncToggle.set(true/false)
//      parent.window.__mutationAsyncToggle.toggle()
$((function () {
    'use strict';

    const NS = 'mutation-async-toggle';
    const PARENT = window.parent;
    const DOC = PARENT.document;
    const BTN_ID = 'mutation-async-toggle-btn';
    const QR_GROUP_NAME = '酒馆保存异步';
    const SETTINGS_KEY = 'tavernHelperToggle';
    const FIELD_KEY = 'mutationAsync';

    function getContext() {
        try {
            return PARENT.SillyTavern?.getContext?.() || null;
        } catch (e) {
            return null;
        }
    }

    // 读取当前开关状态（与 script.js isMutationAsyncEnabled 读取逻辑一致，默认关 = 同步）
    function getState() {
        try {
            const v = getContext()?.extensionSettings?.[SETTINGS_KEY]?.[FIELD_KEY];
            return v === undefined ? false : v === true;
        } catch (e) {
            return false;
        }
    }

    function setState(enabled) {
        const ctx = getContext();
        if (ctx?.extensionSettings) {
            ctx.extensionSettings[SETTINGS_KEY] ??= {};
            ctx.extensionSettings[SETTINGS_KEY][FIELD_KEY] = !!enabled;
            try { ctx.saveSettingsDebounced(); } catch (e) {}
        }
        refreshButtons();
        return getState();
    }

    // 暴露全局 API（供循环任务 / 斜杠命令调用）
    PARENT.window.__mutationAsyncToggle ??= {
        isEnabled: getState,
        set: (v) => setState(!!v),
        toggle: () => setState(!getState()),
    };

    function buildButton() {
        const btn = DOC.createElement('div');
        btn.id = BTN_ID;
        btn.className = 'qr--button menu_button interactable ' + NS;
        btn.innerHTML = '<div class="qr--button-label"><i class="fa-solid fa-bolt"></i></div>';
        btn.addEventListener('click', (event) => {
            event.stopPropagation();
            const next = PARENT.window.__mutationAsyncToggle.toggle();
            PARENT.window.toastr?.[next ? 'success' : 'warning']('mutation 保存异步：' + (next ? '开' : '关'));
        });
        applyState(btn);
        return btn;
    }

    function applyState(btn) {
        const enabled = getState();
        btn.classList.toggle('active', enabled);
        const icon = btn.querySelector('i');
        if (icon) icon.className = enabled ? 'fa-solid fa-bolt' : 'fa-solid fa-bolt-slash';
        btn.title = enabled
            ? 'mutation 保存异步：开（点击切换为同步）'
            : 'mutation 保存异步：关（点击切换为异步）';
    }

    function refreshButtons() {
        DOC.querySelectorAll('#' + BTN_ID).forEach(applyState);
    }

    // 注册到 QR Assistant 扩展 API（可选，方便在 QR Assistant 里白名单/定位）
    function registerWithQrAssistant() {
        try {
            if (!Array.isArray(PARENT.qrAssistantExtensionApi)) PARENT.qrAssistantExtensionApi = [];
            const entry = PARENT.qrAssistantExtensionApi.find((i) => i && i.dom_id === BTN_ID);
            const config = { dom_id: BTN_ID, group_name: QR_GROUP_NAME, button_name: 'fa-solid fa-bolt' };
            if (entry) Object.assign(entry, config);
            else PARENT.qrAssistantExtensionApi.push(config);
            PARENT.quickReplyMenu?.applyWhitelistDOMChanges?.();
        } catch (e) {}
    }

    // 注入按钮（防重复）
    function injectButton() {
        const existing = DOC.getElementById(BTN_ID);
        if (existing) { applyState(existing); return; }

        registerWithQrAssistant();

        const bar = DOC.querySelector('#qr--bar .qr--buttons') || DOC.querySelector('#qr--bar');
        if (!bar) return;

        const wrapper = DOC.createElement('div');
        wrapper.className = 'qr--buttons qr--color';
        wrapper.style.setProperty('--qr--color', 'rgba(0,0,0,0)');
        wrapper.appendChild(buildButton());
        bar.prepend(wrapper);
    }

    // 1s 守护：ST 重绘 QR 栏（切聊天/改设置）后自动把按钮放回去
    setInterval(injectButton, 1000);
    injectButton();
})());
